@pytest.mark.parametrize(
    "failing_method",
    ["thread/archive", "thread/unarchive"],
)
async def test_task_isolated_resume_recycle_failure_is_uncertain_and_fail_closed(
    isolated_task_boundary,
    failing_method,
):
    task_id = 9963
    thread_id = "thread-task-recycle-failure"
