@pytest.mark.asyncio
async def test_fast_turn_uses_actual_priority_proof_when_thread_omits_tier():
    server = CodexAppServer(
        "codex",
        actual_tier_proxy_route=CodexTierProxyRoute(
            "https://upstream.example/v1",
        ),
        require_actual_tier_proof=True,
    )
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()
    proof = CodexTierRequestProof(
        thread_id="thread-fast-proof",
        turn_id="turn-fast-proof",
        parent_thread_id=None,
        requested_tier="priority",
        upstream_reported_tier="auto",
        response_id="resp-fast-proof",
        observed_at=1.0,
    )
    proxy = SimpleNamespace(
        is_alive=True,
        set_thread_tier=MagicMock(),
        wait_for_request_acceptance=AsyncMock(return_value=proof),
        register_thread_parent=MagicMock(),
    )
    server._actual_tier_proxy = proxy

    async def request(method, params, **_kwargs):
        if method == "model/list":
            return {
                "data": [{
                    "id": "gpt-5.6-sol",
                    "serviceTiers": [{"id": "priority"}],
                }],
            }
        if method == "thread/start":
            return {
                "thread": {
                    "id": "thread-fast-proof",
                    "status": {"type": "idle"},
                },
                "serviceTier": None,
            }
        if method == "turn/start":
            def notify_started_input():
                server._handle_notification("turn/started", {
                    "threadId": "thread-fast-proof",
                    "turn": {
                        "id": "turn-fast-proof",
                        "status": "inProgress",
                    },
                })
                server._handle_notification("item/started", {
                    "threadId": "thread-fast-proof",
                    "turnId": "turn-fast-proof",
                    "item": {
                        "id": "input-fast-proof",
                        "type": "userMessage",
                        "clientId": params["clientUserMessageId"],
                    },
                })

            asyncio.get_running_loop().call_soon(notify_started_input)
            return {"turn": {"id": "turn-fast-proof"}}
        raise AssertionError(method)

    server._request = AsyncMock(side_effect=request)
    process, _thread_id = await server.start_turn(
        prompt="fast with proof",
        cwd="/tmp",
        model="gpt-5.6-sol",
        effort="high",
        resume_session_id=None,
        git_env=None,
        task_id=902,
        codex_service_tier="priority",
    )

    thread_call = server._request.await_args_list[1]
    fast_config = thread_call.args[1]["config"]
    assert fast_config["features"] == {
        "enable_request_compression": False,
        "apps": False,
        "enable_mcp_apps": False,
        "multi_agent": False,
        "multi_agent_v2": {
            "enabled": False,
            "max_concurrent_threads_per_session": 1,
            "hide_spawn_agent_metadata": True,
        },
        "enable_fanout": False,
        "memories": False,
        "realtime_conversation": False,
        "remote_compaction_v2": True,
    }
    assert fast_config["agents"] == {
        "max_threads": 1,
        "max_depth": 1,
    }
    assert fast_config["memories"] == {
        "generate_memories": False,
        "use_memories": False,
        "dedicated_tools": False,
    }
    assert thread_call.args[1]["approvalsReviewer"] == "user"
    assert server._request.await_args_list[2].args[1]["approvalsReviewer"] == (
        "user"
    )
    proxy.set_thread_tier.assert_called_once_with(
        "thread-fast-proof",
        "priority",
    )
    proxy.wait_for_request_acceptance.assert_awaited_once_with(
        "thread-fast-proof",
        "turn-fast-proof",
        "priority",
        timeout=60.0,
    )
    assert json.loads((await process.stdout.readline()).decode())["type"] == (
        "thread.started"
    )
    event = json.loads((await process.stdout.readline()).decode())
    assert event["service_tier_request_verified"] is True
    assert event["admitted_service_tier"] == "priority"
    assert event["upstream_reported_service_tier"] == "auto"
    assert event["upstream_response_id"] == "resp-fast-proof"


