@pytest.mark.asyncio
@pytest.mark.skipif(
    os.name != "posix",
    reason="stdio protocol capture uses a POSIX executable fixture",
)
async def test_stdio_protocol_delivers_skill_catalog_in_model_visible_input(
    tmp_path,
    monkeypatch,
):
    fake_binary = tmp_path / "codex-schema-peer"
    capture_path = tmp_path / "model-visible-input.json"
    _write_schema_filtering_app_server(fake_binary)
    monkeypatch.setenv(
        "CCM_TEST_CODEX_PROTOCOL_CAPTURE",
        str(capture_path),
    )
    server = CodexAppServer(
        str(fake_binary),
        codex_home=tmp_path / "codex-home",
    )

    try:
        await server.start_turn(
            prompt="review this",
            cwd=str(tmp_path),
            model="gpt-5.6-sol",
            effort="high",
            resume_session_id=None,
            git_env=None,
            task_id=55,
            skill_context=(
                "## Available Skills\n"
                "- **review**: Review changes\n\n"
                "## User Skills\n"
                "- **release policy** (id=9): Follow release rules"
            ),
        )
        captured = json.loads(capture_path.read_text(encoding="utf-8"))
    finally:
        await server.shutdown()

    assert captured["dropped_fields"] == []
    model_text = captured["model_visible_input"][0]["text"]
    assert model_text == (
        "<ccm-task-skill-context>\n"
        "## Available Skills\n"
        "- **review**: Review changes\n\n"
        "## User Skills\n"
        "- **release policy** (id=9): Follow release rules\n"
        "</ccm-task-skill-context>\n\n"
        "review this"
    )
    assert model_text.count("<ccm-task-skill-context>") == 1
    assert model_text.count("</ccm-task-skill-context>") == 1


