@pytest.mark.asyncio
async def test_turn_process_wait_includes_runtime_cleanup_barrier():
    cleanup_started = threading.Event()
    release_cleanup = threading.Event()

    async def interrupt():
        return None

    def cleanup() -> None:
        cleanup_started.set()
        release_cleanup.wait(timeout=5)

    process = CodexTurnProcess(1, interrupt)
    process.set_runtime_cleanup(cleanup)
    process.finish(0)
    waiter = asyncio.create_task(process.wait())
    assert await asyncio.to_thread(cleanup_started.wait, 1)
    await asyncio.sleep(0)
    assert not waiter.done()

    release_cleanup.set()
    assert await asyncio.wait_for(waiter, timeout=1) == 0


@pytest.mark.asyncio
async def test_turn_process_cleanup_delays_waiter_cancellation():
    cleanup_started = threading.Event()
    release_cleanup = threading.Event()

    async def interrupt():
        return None

    def cleanup() -> None:
        cleanup_started.set()
        release_cleanup.wait(timeout=5)

    process = CodexTurnProcess(1, interrupt)
    process.set_runtime_cleanup(cleanup)
    process.finish(0)
    waiter = asyncio.create_task(process.wait())
    assert await asyncio.to_thread(cleanup_started.wait, 1)
    await asyncio.sleep(0)
    waiter.cancel()
    await asyncio.sleep(0)
    assert not waiter.done()

    release_cleanup.set()
    with pytest.raises(asyncio.CancelledError):
        await asyncio.wait_for(waiter, timeout=1)


